private static async Task SimulateEscapeAsync()
{
    Keyboard keyboard = Keyboard.current;
    bool created = keyboard == null;
    if (created) keyboard = InputSystem.AddDevice<Keyboard>();
    try
    {
        InputSystem.QueueStateEvent(keyboard, new KeyboardState(Key.Escape));
        await UniTask.NextFrame();
        await UniTask.NextFrame();
        InputSystem.QueueStateEvent(keyboard, default(KeyboardState));
        await UniTask.NextFrame();
    }
    finally
    {
        if (created && keyboard != null) InputSystem.RemoveDevice(keyboard);
    }
}
