private static async Task<string> ConfirmError(ServiceContainer container, UIService ui)
{
    var deadline = new Deadline();
    var sb = Begin("ConfirmError");
    var steps = new List<string>();
    string[] kinds = { "error" };

    string before = VisiblePages(ui);
    await WaitUntil(() => DialogOkButton(container, kinds) != null, "错误 UIDialog 的 OkButton 可见", deadline,
        () => "未取到活动错误弹窗（DialogService kind=error）；" + PageDiagnostics(ui));
    steps.Add("assert=活动 UIDialog(kind=error).OkButton 就绪");

    Button ok = await WaitButtonReachable(() => DialogOkButton(container, kinds), "错误弹窗 OkButton", ui, deadline);
    ClickReport click = Click(ok, "Dialog.Error.OkButton");
    steps.Add("click=" + click.Summary);

    await WaitUntil(() => DialogOkButton(container, kinds) == null, "错误模态关闭", deadline,
        () => "点击 OkButton 后错误模态仍在；" + PageDiagnostics(ui));
    steps.Add("assert=错误模态关闭");

    await WaitUntil(() => IsLobbyOperational(ui), "大厅可操作（Btn_QuickEnter 首射线命中）", deadline,
        () => "错误弹窗已关但未回大厅/仍被其他页占用；" + PageDiagnostics(ui));
    steps.Add("assert=大厅可操作");

    string after = VisiblePages(ui);
    return Finish(sb, before, after, steps, click);
}

private static async Task<string> CancelWait(ServiceContainer container, UIService ui)
{
