    steps.Add("input=InputSystem QueueStateEvent Keyboard Escape 按下/释放（真实设备状态事件）");

    await WaitUntil(() => IsPageOpen(ui, PageIds.Page_Settings), "Esc 打开 Page_Settings", deadline,
        () => "Esc 未打开真实设置页；" + PageDiagnostics(ui));
    steps.Add("assert=Esc 打开真实 Page_Settings");

    Button exit = await WaitButtonReachable("Btn_ExitMatch", "设置页退出对局钮", ui, deadline);
