    steps.Add("click=" + exitClick.Summary);

    await WaitUntil(() => DialogOkButton(container, confirmKinds) != null, "退出确认 UIDialog 的 OkButton 可见", deadline,
        () => "点击退出对局后未出现真实确认弹窗；" + PageDiagnostics(ui));
    steps.Add("assert=退出确认模态可见");

    Button ok = await WaitButtonReachable(() => DialogOkButton(container, confirmKinds), "退出确认 OkButton", ui, deadline);
    ClickReport okClick = Click(ok, "Dialog.Confirm.OkButton");
    steps.Add("click=" + okClick.Summary);

    await WaitUntil(() => !IsPageOpen(ui, PageIds.Page_Settings) && DialogOkButton(container, confirmKinds) == null,
        "设置页与确认模态关闭", deadline,
        () => "确认退出后设置页/模态仍在；" + PageDiagnostics(ui));
    steps.Add("assert=设置页/确认模态关闭");

    await WaitUntil(() => IsLobbyOperational(ui), "大厅可操作（Btn_QuickEnter 首射线命中）", deadline,
        () => "退出对局后未回大厅；" + PageDiagnostics(ui));
    steps.Add("assert=大厅可操作");

    await WaitUntil(() => ReadRoomFacts(container, null).IsEmpty, "房间投影为空", deadline,
        () => "退出对局后房间投影未清；" + RoomDiagnostics(container, FindPageRoot("Page_Room")));
