private static async Task<Button> WaitButtonReachable(Func<Button> getter, string purpose, UIService ui, Deadline deadline)
{
    Button last = null;
    Probe probe = null;
    while (true)
    {
        last = getter();
        if (last != null && last.IsInteractable())
        {
            probe = ProbeButton(last);
            if (probe.Reaches) return last;
        }
        if (deadline.Expired)
        {
            string detail = last == null
                ? "目标 Button 不存在/未激活"
                : (!last.IsInteractable()
                    ? "按钮存在但禁用（" + DisabledReason(last) + "）"
                    : "按钮可试但首射线未到达目标，first_hit=" + probe?.FirstHitPath + "，handler=" + probe?.HandlerName);
            throw new InvalidOperationException("超时(" + deadline.Seconds.ToString("0", CultureInfo.InvariantCulture)
                + "s) 等待 " + purpose + "：" + detail + "；" + PageDiagnostics(ui));
        }
        await Task.Yield();
    }
}

private static async Task SimulateEscapeAsync()
{
    Keyboard keyboard = Keyboard.current;
    bool created = keyboard == null;
    if (created) keyboard = InputSystem.AddDevice<Keyboard>();
    try
    {
        InputSystem.QueueStateEvent(keyboard, new KeyboardState(Key.Escape));
        await UniTask.NextFrame();
        await UniTask.NextFrame();
        InputSystem.QueueStateEvent(keyboard, default(KeyboardState));
        await UniTask.NextFrame();
    }
    finally
    {
        if (created && keyboard != null) InputSystem.RemoveDevice(keyboard);
    }
}

private static Button DialogOkButton(ServiceContainer container, string[] kinds)
{
    UIDialog dialog;
    return TryGetDialog(container, kinds, out dialog) ? dialog.OkButton : null;
}

private static bool TryGetDialog(ServiceContainer container, string[] kinds, out UIDialog dialog)
{
    dialog = null;
    DialogService dialogs = TryResolve<DialogService>(container);
    if (dialogs == null) return false;
    for (int i = 0; i < kinds.Length; i++)
    {
        UIDialog candidate;
        if (dialogs.TryGetActiveDialog(kinds[i], out candidate) && candidate != null)
        {
            dialog = candidate;
            return true;
        }
    }
    return false;
}

